#include <algorithm>
#include <cstddef>
#include <execution>
#include <functional>
#include <numeric>
#include <vector>

long long sumOfSquares(const std::vector<int>& values)
{
    return std::transform_reduce(std::execution::par, values.begin(), values.end(), 0LL, std::plus{},
        [](int x) { return static_cast<long long>(x) * x; });
}

std::size_t countMultiples(const std::vector<int>& values, int divisor)
{
    return static_cast<std::size_t>(std::count_if(std::execution::par, values.begin(), values.end(),
        [divisor](int x) { return x % divisor == 0; }));
}

unitTests:
std::vector<int> upTo(int n) { std::vector<int> v(static_cast<std::size_t>(n)); std::iota(v.begin(), v.end(), 1); return v; }
TEST("sumOfSquares") { CHECK_EQ(sumOfSquares({ 1, 2, 3 }), 14LL); CHECK_EQ(sumOfSquares({}), 0LL); CHECK_EQ(sumOfSquares(upTo(100000)), 333338333350000LL); }
TEST("countMultiples") { CHECK_EQ(countMultiples(upTo(1000), 7), 142u); CHECK_EQ(countMultiples(upTo(1000000), 1000), 1000u); CHECK_EQ(countMultiples({}, 3), 0u); }

